  ctx.fillStyle = '#3a2c20'; ctx.fillRect(p.x - 4, p.y - 68, 8, 20);
  ctx.fillStyle = '#7c6a4c'; ctx.fillRect(p.x - 8, p.y - 50, 16, 6);
