export class Player {
  constructor(clsKey = 'blade') {
    this.cls = CLASSES[clsKey] || CLASSES.blade;
    this.clsKey = clsKey;
    this.x = 760; this.y = 1780;
    this.vx = 0; this.vy = 0;
    this.r = 15;
    this.facing = -0.4;
    this.moveDir = { x: 0, y: 0 };
    this.hp = this.cls.maxHp; this.maxHp = this.cls.maxHp;
    this.sta = this.cls.maxSta; this.maxSta = this.cls.maxSta;
    this.mp = this.cls.maxMp; this.maxMp = this.cls.maxMp;
    this.atk = this.cls.atk;
    this.speed = this.cls.speed;
    this.crit = this.cls.crit;
    this.level = 1; this.xp = 0; this.xpNext = 60;
    this.gold = 0; this.shards = 0;
    this.walk = 0; this.bob = 0;
    this.moving = false;
    this.attack = null; // {t, dur, combo, hit}
    this.attackCd = 0;
    this.dash = 0; this.dashCd = 0;
    this.skillCd = 0; this.ultCd = 0;
    this.invuln = 0;
    this.hurtFlash = 0;
    this.comboTimer = 0;
    this.swingT = 0;
    this.dead = false;
    this.kills = 0;
    this.time = 0;
    this.stepTimer = 0;
    this.lastSafe = { x: this.x, y: this.y };
    this.levelPulse = 0;
  }
  get atkPower() { return this.cls.atk * this.atk; }
  canAttack() { return !this.attack && this.attackCd <= 0 && !this.dead; }
  startAttack() {
    const combo = this.comboTimer > 0 ? (this.comboCount % 3) + 1 : 1;
    this.comboCount = combo;
    this.comboTimer = 1.1;
    this.attack = { t: 0, dur: combo === 3 ? 0.42 : 0.3, combo, hit: false, applied: false };
    this.attackCd = combo === 3 ? 0.26 : 0.06;
    return this.attack;
  }
  addXp(n, onLevel) {
    this.xp += n;
    while (this.xp >= this.xpNext) {
      this.xp -= this.xpNext; this.level++;
      this.xpNext = Math.round(60 + this.level * 42 + this.level ** 1.6 * 6);
      this.maxHp = Math.round(this.cls.maxHp + (this.level - 1) * 12);
      this.maxSta = this.cls.maxSta + (this.level - 1) * 3;
      this.maxMp = this.cls.maxMp + (this.level - 1) * 5;
      this.hp = this.maxHp; this.sta = this.maxSta; this.mp = this.maxMp;
      this.atk = +(this.cls.atk * (1 + (this.level - 1) * 0.10)).toFixed(2);
      this.levelPulse = 1;
      onLevel?.();
    }
  }
  heal(n) {
    const before = this.hp;
    this.hp = clamp(this.hp + n, 0, this.maxHp);
    return this.hp - before;
  }
  update(dt, time, input) {
    this.time = time;
    if (this.dead) return;
    this.invuln = Math.max(0, this.invuln - dt);
    this.hurtFlash = Math.max(0, this.hurtFlash - dt * 3.2);
    this.attackCd = Math.max(0, this.attackCd - dt);
    this.dashCd = Math.max(0, this.dashCd - dt);
    this.skillCd = Math.max(0, this.skillCd - dt);
    this.ultCd = Math.max(0, this.ultCd - dt);
    this.comboTimer = Math.max(0, this.comboTimer - dt);
    if (this.comboTimer === 0) this.comboCount = 0;
    this.levelPulse = Math.max(0, this.levelPulse - dt);

    if (this.attack) {
      this.attack.t += dt;
      if (this.attack.t >= this.attack.dur) this.attack = null;
    }

    const mv = input.move;
    const len = Math.hypot(mv.x, mv.y);
    this.moving = len > 0.12;
    let sp = this.speed;
    if (this.attack) sp *= 0.34;
    if (this.dash > 0) {
      this.dash -= dt;
      this.invuln = Math.max(this.invuln, 0.03);
      sp = this.speed * 2.65;
      this.moving = true;
      if (Math.random() < 0.6) {
        input.onDashTrail?.();
      }
    }
    if (this.moving) {
      const nx = mv.x / (len || 1), ny = mv.y / (len || 1);
      this.facing = lerp(this.facing, Math.atan2(ny, nx), 1 - Math.exp(-18 * dt));
      this.vx = nx * sp;
      this.vy = ny * sp;
      this.walk += dt * (this.dash > 0 ? 16 : 11) * (sp / this.speed);
      this.stepTimer -= dt;
      if (this.stepTimer <= 0 && this.dash <= 0) { this.stepTimer = 0.26; input.onStep?.(); }
    } else {
      this.vx = approach(this.vx, 0, 1400 * dt);
      this.vy = approach(this.vy, 0, 1400 * dt);
      this.walk *= Math.pow(0.001, dt);
    }
    this.bob = this.moving ? Math.sin(this.walk) * 2.4 : Math.sin(time * 2.2) * 1.1;

    // regen
    if (this.dash <= 0) this.sta = Math.min(this.maxSta, this.sta + dt * 21);
    this.mp = Math.min(this.maxMp, this.mp + dt * 3.1);
    if (time - (this.lastHurt || -10) > 4) this.hp = Math.min(this.maxHp, this.hp + dt * 1.6);
  }
  hurt(n, game) {
    if (this.invuln > 0 || this.dead) return false;
    n = Math.round(n);
    this.hp -= n;
    this.hurtFlash = 1;
    this.lastHurt = this.time;
    this.invuln = 0.62;
    game?.onPlayerHurt?.(n);
    if (this.hp <= 0) { this.hp = 0; this.dead = true; }
    return true;
  }
  draw(ctx, time) {
    const c = this.cls;
    const flicker = this.invuln > 0 && Math.floor(time * 24) % 2 === 0;
    ctx.save();
    ctx.translate(this.x, this.y);
    // shadow
    ctx.fillStyle = 'rgba(3,8,6,.42)';
    ctx.beginPath(); ctx.ellipse(4, 2, 22, 8, 0, 0, TAU); ctx.fill();
    if (this.dead) {
      ctx.rotate(-1.2);
      ctx.globalAlpha = 0.7;
      drawBody(ctx, this, c, time, true);
      ctx.restore();
      return;
    }
    if (this.dash > 0) {
      ctx.globalAlpha *= 0.7;
    }
    if (flicker) ctx.globalAlpha *= 0.55;
    drawBody(ctx, this, c, time, false);
    ctx.restore();
    if (this.dash > 0) {
      // speed streaks
      ctx.save();
      ctx.strokeStyle = 'rgba(180,255,225,.26)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 3; i++) {
        const a = this.facing + Math.PI + (i - 1) * 0.18;
        ctx.beginPath();
        ctx.moveTo(this.x + Math.cos(a) * 16, this.y + Math.sin(a) * 12 - 24);
        ctx.lineTo(this.x + Math.cos(a) * (44 + i * 12), this.y + Math.sin(a) * 30 - 28);
        ctx.stroke();
      }
      ctx.restore();
    }
  }
}

function drawBody(ctx, p, c, time, dead) {
  const bob = p.bob;
  const walk = p.walk;
  const swing = Math.sin(walk) * (p.moving ? 1 : 0);
  const facingX = Math.cos(p.facing);
  const facingY = Math.sin(p.facing);
  const flip = facingX < -0.1 ? -1 : 1;
  const lean = p.moving ? clamp(facingX, -1, 1) * 0.10 : 0;

  ctx.save();
  ctx.translate(0, bob);
  // cloak behind
  const capeSway = Math.sin(time * 3 + walk * 0.6) * 3;
  ctx.fillStyle = c.coat2;
  ctx.beginPath();
  ctx.moveTo(-11, -50);
  ctx.quadraticCurveTo(-22 - facingX * 6, -26 + capeSway, -16 - facingX * 9, -3 + capeSway * 0.4);
  ctx.lineTo(13 - facingX * 7, -2 - capeSway * 0.3);
  ctx.quadraticCurveTo(19 - facingX * 4, -28, 12, -50);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,.24)'; ctx.lineWidth = 1; ctx.stroke();
  // legs
  ctx.strokeStyle = c.leather;
  ctx.lineCap = 'round';
  ctx.lineWidth = 8;
  ctx.beginPath(); ctx.moveTo(-5, -24); ctx.lineTo(-7 + swing * 6, -6); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(6, -24); ctx.lineTo(8 - swing * 6, -6); ctx.stroke();
  ctx.strokeStyle = '#1d1712'; ctx.lineWidth = 9;
  ctx.beginPath(); ctx.moveTo(-7 + swing * 6, -8); ctx.lineTo(-8 + swing * 8, -1); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(8 - swing * 6, -8); ctx.lineTo(9 - swing * 8, -1); ctx.stroke();
  // torso
  ctx.save();
  ctx.rotate(lean);
  const grd = ctx.createLinearGradient(-14, -54, 16, -24);
  grd.addColorStop(0, c.coat2);
  grd.addColorStop(0.55, c.coat);
  grd.addColorStop(1, c.coat2);
  ctx.fillStyle = grd;
  ctx.beginPath();
  ctx.moveTo(-12, -50);
  ctx.quadraticCurveTo(-16, -38, -12, -22);
  ctx.lineTo(-6, -18);
  ctx.lineTo(8, -18);
  ctx.lineTo(13, -24);
  ctx.quadraticCurveTo(15, -40, 10, -50);
  ctx.quadraticCurveTo(0, -56, -12, -50);
  ctx.closePath();
  ctx.fill();
  // chest armor plate / tunic detail
  ctx.fillStyle = c.leather;
  ctx.beginPath();
  ctx.moveTo(-8, -47); ctx.quadraticCurveTo(0, -52, 8, -47); ctx.lineTo(7, -33); ctx.quadraticCurveTo(0, -30, -7, -33); ctx.closePath(); ctx.fill();
  // belt
  ctx.fillStyle = '#241b14';
  ctx.fillRect(-12, -26, 25, 5);
  ctx.fillStyle = c.accent;
  ctx.fillRect(-2, -27, 5, 7);
  // collar trim
  ctx.strokeStyle = c.trim; ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.moveTo(-9, -48); ctx.quadraticCurveTo(0, -43, 9, -48); ctx.stroke();
  // shoulder pads
  ctx.fillStyle = c.coat2;
  ctx.beginPath(); ctx.ellipse(-12, -46, 7, 6, -0.3, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.ellipse(11, -46, 7, 6, 0.3, 0, TAU); ctx.fill();
  ctx.fillStyle = c.trim; ctx.globalAlpha *= 0.55;
  ctx.beginPath(); ctx.ellipse(-12, -47, 3, 2, -0.3, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.ellipse(11, -47, 3, 2, 0.3, 0, TAU); ctx.fill();
  ctx.globalAlpha /= 0.55;

  // head
  const hx = facingX * 2.4;
  ctx.fillStyle = c.skin;
  ctx.beginPath(); ctx.arc(hx, -58, 9.5, 0, TAU); ctx.fill();
  // hair
  ctx.fillStyle = c.hair;
  if (p.clsKey === 'guardian') {
    ctx.beginPath(); ctx.arc(hx, -59, 10.4, Math.PI * 0.95, Math.PI * 2.05); ctx.fill();
    ctx.fillStyle = '#8794a0';
    ctx.beginPath(); ctx.arc(hx, -61, 10, Math.PI, TAU); ctx.fill();
    ctx.fillStyle = c.accent;
    ctx.fillRect(hx - 2, -70, 4, 8);
    ctx.fillStyle = 'rgba(255,220,140,.55)'; ctx.fillRect(hx - 8, -60, 16, 2);
  } else if (p.clsKey === 'ronin') {
    ctx.beginPath();
    ctx.arc(hx, -60, 10, Math.PI * 0.85, Math.PI * 2.15);
    ctx.fill();
    ctx.beginPath(); ctx.moveTo(hx - 9, -59); ctx.lineTo(hx - 15, -64); ctx.lineTo(hx - 7, -66); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#15141c';
    ctx.beginPath(); ctx.arc(hx + 1, -69, 5, 0, TAU); ctx.fill();
  } else {
    ctx.beginPath();
    ctx.moveTo(hx - 10, -58);
    ctx.quadraticCurveTo(hx - 12, -69, hx - 3, -70);
    ctx.quadraticCurveTo(hx + 8, -74, hx + 10, -63);
    ctx.lineTo(hx + 11, -57);
    ctx.lineTo(hx + 3, -62);
    ctx.lineTo(hx - 2, -56);
    ctx.lineTo(hx - 6, -62);
    ctx.closePath(); ctx.fill();
  }
  // eyes
  const ex = hx + facingX * 3.2;
  ctx.fillStyle = '#1a1410';
  ctx.beginPath(); ctx.arc(ex - 3.4 * flip, -58, 1.5, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.arc(ex + 2.6 * flip, -58, 1.5, 0, TAU); ctx.fill();
  // scarf
  if (p.clsKey === 'ronin') {
    ctx.strokeStyle = '#b23a3a'; ctx.lineWidth = 3.4; ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(-6, -49);
    ctx.quadraticCurveTo(-14 - facingX * 4 + Math.sin(time * 5) * 2, -44, -20 - facingX * 6, -38 + Math.sin(time * 4) * 3);
    ctx.stroke();
  }

  // arms + weapon
  const attacking = p.attack;
  let weaponAng = p.facing;
  let hx2 = 12, hy2 = -36;
  if (attacking) {
    const t = clamp(attacking.t / attacking.dur, 0, 1);
    const back = attacking.combo === 2 ? -1.1 : -0.65;
    const end = attacking.combo === 2 ? 2.7 : 1.5;
    weaponAng = p.facing + lerp(back, end, t * t * (3 - 2 * t));
    hx2 = Math.cos(weaponAng) * 8;
    hy2 = -34 + Math.sin(weaponAng) * 3;
  } else if (p.moving) {
    weaponAng = p.facing + 0.8 + Math.sin(walk) * 0.12;
  } else {
    weaponAng = p.facing + 2.3;
  }
  // back arm
  ctx.strokeStyle = c.coat2; ctx.lineWidth = 6; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(10, -45); ctx.lineTo(15 + facingX * 2, -32); ctx.stroke();
  ctx.fillStyle = c.skin;
  ctx.beginPath(); ctx.arc(15 + facingX * 2, -31, 3.4, 0, TAU); ctx.fill();

  // weapon render
  drawSword(ctx, hx2, hy2, weaponAng, c, attacking, p);
  // front arm holding sword
  ctx.strokeStyle = c.coat; ctx.lineWidth = 6;
  ctx.beginPath(); ctx.moveTo(-8, -45); ctx.lineTo(hx2 * 0.7, hy2 + 4); ctx.stroke();
  ctx.fillStyle = c.skin;
  ctx.beginPath(); ctx.arc(hx2 * 0.7 + 2, hy2 + 3, 3.2, 0, TAU); ctx.fill();

  // glow chest emblem
  ctx.fillStyle = c.trim; ctx.globalAlpha *= 0.85;
  ctx.beginPath(); ctx.arc(0, -37, 2.4, 0, TAU); ctx.fill();
  ctx.restore();
  ctx.restore();
  ctx.globalAlpha = 1;
}

function drawSword(ctx, hx, hy, ang, c, attacking, p) {
  ctx.save();
  ctx.translate(hx, hy);
  ctx.rotate(ang);
  const len = attacking ? 48 : 38;
  // blade
  const g = ctx.createLinearGradient(0, 0, len, 0);
  g.addColorStop(0, '#8fa7ab');
  g.addColorStop(0.25, c.weapon);
  g.addColorStop(0.8, '#ffffff');
  g.addColorStop(1, c.trim);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(6, -2.2);
  ctx.lineTo(len - 7, -1.8);
  ctx.lineTo(len, 0);
  ctx.lineTo(len - 7, 1.8);
  ctx.lineTo(6, 2.2);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,.55)'; ctx.lineWidth = 0.8;
  ctx.beginPath(); ctx.moveTo(10, -0.6); ctx.lineTo(len - 6, -0.4); ctx.stroke();
  // hilt
  ctx.fillStyle = '#2b2118';
  ctx.fillRect(-4, -3.4, 10, 6.8);
  ctx.fillStyle = c.accent;
  ctx.fillRect(4, -5.4, 3, 10.8);
  ctx.beginPath(); ctx.arc(-6, 0, 2.6, 0, TAU); ctx.fill();
  ctx.restore();
  if (attacking) {
    const t = clamp(attacking.t / attacking.dur, 0, 1);
    ctx.save();
    ctx.translate(p.x, p.y - 30);
    ctx.rotate(p.facing);
    ctx.strokeStyle = `rgba(220,255,240,${0.5 * (1 - t)})`;
    ctx.lineWidth = 5 * (1 - t) + 1;
    ctx.beginPath();
    const sweep = attacking.combo === 2 ? 2.9 : 1.9;
    const a0 = p.facing - sweep * 0.5 + sweep * t;
    ctx.arc(0, 0, 50, a0 - 0.9, a0 + 0.2);
    ctx.stroke();
    ctx.strokeStyle = `rgba(157,245,200,${0.28 * (1 - t)})`;
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(0, 0, 56, a0 - 0.9, a0 + 0.2); ctx.stroke();
    ctx.restore();
  }
}

import { TAU, clamp, lerp, rand, dist, angleTo, mulberry32 } from './util.js';

export const ENEMY_TYPES = {
  slime: {
    name: 'Melma Verdegrigia', hp: 48, speed: 66, dmg: 9, r: 19, xp: 16, gold: 7,
    aggro: 320, windup: 0.55, recover: 1.05, reach: 44, kind: 'slime',
  },
  wolf: {
    name: 'Lupo Crepuscolare', hp: 64, speed: 128, dmg: 12, r: 17, xp: 22, gold: 9,
    aggro: 430, windup: 0.4, recover: 0.82, reach: 40, kind: 'wolf',
  },
  skeleton: {
    name: 'Sentinella d\'Ossa', hp: 96, speed: 74, dmg: 15, r: 17, xp: 34, gold: 15,
    aggro: 400, windup: 0.52, recover: 0.9, reach: 52, kind: 'skeleton', ranged: true,
  },
  wisp: {
    name: 'Fuoco Fatuo', hp: 40, speed: 92, dmg: 11, r: 15, xp: 26, gold: 12,
    aggro: 440, windup: 0.7, recover: 1.3, reach: 300, kind: 'wisp', ranged: true,
  },
  warden: {
    name: 'Guardiano Sepolto', hp: 280, speed: 78, dmg: 21, r: 24, xp: 110, gold: 60,
    aggro: 460, windup: 0.72, recover: 1.1, reach: 66, kind: 'warden', elite: true,
  },
  boss: {
    name: 'VERBENA', hp: 1500, speed: 60, dmg: 24, r: 72, xp: 800, gold: 400,
    aggro: 700, kind: 'boss',
  },
};

let uid = 1;

export class Enemy {
  constructor(type, x, y, opts = {}) {
    const cfg = ENEMY_TYPES[type];
    this.id = uid++;
    this.type = type;
    this.cfg = cfg;
    this.x = x; this.y = y;
    this.home = { x, y };
    this.hp = cfg.hp * (opts.hpMult || 1);
    this.maxHp = this.hp;
    this.r = cfg.r;
    this.speed = cfg.speed;
    this.dmg = cfg.dmg;
    this.elite = !!cfg.elite || !!opts.elite;
    this.scale = this.elite ? 1.28 : 1;
    this.state = 'idle';
    this.timer = rand(0, 1.2);
    this.facing = rand(0, TAU);
    this.vx = 0; this.vy = 0;
    this.walk = rand(0, 10);
    this.flash = 0;
    this.hurtStun = 0;
    this.dead = false;
    this.deathT = 0;
    this.spawnT = 0.6;
    this.aggro = false;
    this.attackCd = rand(0.4, 1.4);
    this.wander = { x, y };
    this.barT = 0;
    this.telegraph = 0;
    this.phase = 1;
    this.pattern = 0;
    this.bossTimer = 0;
    this.awake = false;
    this.bossAttack = null;
    this.hazardDone = false;
    this.chargeDir = { x: 0, y: 0 };
    this.temp = 0;
  }

  hurt(n, game, crit = false, fromX = 0, fromY = 0) {
    if (this.dead) return;
    this.hp -= n;
    this.flash = 1;
    this.hurtStun = this.type === 'boss' ? 0.02 : 0.22;
    this.barT = 3;
    if (this.type !== 'boss') {
      const a = Math.atan2(this.y - fromY, this.x - fromX);
      const kb = this.elite ? 60 : 170;
      this.vx += Math.cos(a) * kb;
      this.vy += Math.sin(a) * kb;
    }
    this.aggro = true;
    game?.addEffect?.('hit', { x: this.x, y: this.y - 34, crit });
    if (this.hp <= 0) {
      this.hp = 0;
      this.die(game);
    }
  }

  die(game) {
    this.dead = true;
    this.deathT = 0;
    this.state = 'dead';
    game?.onEnemyKilled?.(this);
  }

  update(dt, game) {
    if (this.dead) { this.deathT += dt; return; }
    this.flash = Math.max(0, this.flash - dt * 4);
    this.barT = Math.max(0, this.barT - dt);
    this.hurtStun = Math.max(0, this.hurtStun - dt);
    this.spawnT = Math.max(0, this.spawnT - dt);
    this.attackCd = Math.max(0, this.attackCd - dt);
    this.timer -= dt;
    this.telegraph = Math.max(0, this.telegraph - dt);
    // knockback decay
    this.vx *= Math.pow(0.002, dt);
    this.vy *= Math.pow(0.002, dt);
    this.x += this.vx * dt;
    this.y += this.vy * dt;

    if (this.type === 'boss') { this.updateBoss(dt, game); return; }
    if (this.spawnT > 0 || this.hurtStun > 0) return;

    const p = game.player;
    const d = dist(this, p);
    const safe = game.isPlayerSafe;
    if (this.aggro && (safe || p.dead || d > this.cfg.aggro * 1.8)) {
      this.aggro = false;
      this.state = 'idle';
      this.timer = rand(0.5, 1.5);
    }
    if (!this.aggro && !safe && d < this.cfg.aggro) {
      this.aggro = true;
      this.state = 'chase';
      this.timer = 0;
    }

    if (!this.aggro) {
      // gentle wander around home
      if (this.timer <= 0) {
        this.timer = rand(1.6, 3.4);
        const a = rand(0, TAU), rr = rand(20, 90);
        this.wander = {
          x: clamp(this.home.x + Math.cos(a) * rr, 80, 4520),
          y: clamp(this.home.y + Math.sin(a) * rr, 80, 2920),
        };
      }
      const dx = this.wander.x - this.x, dy = this.wander.y - this.y;
      const dd = Math.hypot(dx, dy);
      if (dd > 8) {
        this.move(dx / dd * this.speed * 0.22 * dt, dy / dd * this.speed * 0.22 * dt, game);
        this.facing = Math.atan2(dy, dx);
        this.walk += dt * 2.5;
      }
      return;
    }

    this.facing = Math.atan2(p.y - this.y, p.x - this.x);

    switch (this.state) {
      case 'idle':
      case 'chase': {
        const keep = this.type === 'wisp' ? 240 : this.type === 'skeleton' && this.attackCd > 1.2 ? 150 : this.cfg.reach * 0.72;
        if (d > keep) {
          const sp = this.speed * (this.state === 'idle' ? 0.6 : 1);
          this.move((p.x - this.x) / d * sp * dt, (p.y - this.y) / d * sp * dt, game);
          this.walk += dt * sp / 34;
        } else if (this.type === 'wisp') {
          this.move(-(p.x - this.x) / d * this.speed * 0.5 * dt, -(p.y - this.y) / d * this.speed * 0.5 * dt, game);
        }
        if (this.attackCd <= 0) this.beginAttack(d, game);
        break;
      }
      case 'windup': {
        this.telegraph = 1;
        if (this.timer <= 0) this.releaseAttack(d, game);
        break;
      }
      case 'attack': {
        if (this.timer <= 0) {
          this.state = 'recover';
          this.timer = this.cfg.recover;
          this.attackCd = this.cfg.recover + rand(0.3, 0.9);
        }
        break;
      }
      case 'recover': {
        if (this.timer <= 0) this.state = 'chase';
        break;
      }
      default: this.state = 'chase';
    }
  }

  beginAttack(d, game) {
    this.state = 'windup';
    this.timer = this.cfg.windup;
    this.telegraph = 1;
    this.attackCd = this.cfg.recover + rand(0.5, 1.3);
    const p = game.player;
    if (this.type === 'wolf') {
      this.chargeDir = { x: (p.x - this.x) / (d || 1), y: (p.y - this.y) / (d || 1) };
    }
    if (this.type === 'skeleton' && d > 110 && d < 420 && Math.random() < 0.55) {
      this.state = 'cast';
      this.timer = 0.62;
      this.temp = 1;
      this.attackCd = 1.9;
    }
    if (this.type === 'warden') {
      this.state = 'slamWindup';
      this.timer = 1.0;
      this.temp = 0;
    }
    game.audio?.play('deny');
  }

  releaseAttack(d, game) {
    const p = game.player;
    if (this.type === 'wolf') {
      this.state = 'charge';
      this.timer = 0.34;
      this.dashSpeed = 560;
      this.hitPlayer = false;
      game.audio?.play('swing');
    } else if (this.type === 'slime') {
      this.state = 'hop';
      this.timer = 0.34;
      this.dashSpeed = 330;
      this.hitPlayer = false;
      game.audio?.play('swing');
    } else if (this.type === 'skeleton') {
      this.state = 'recover';
      this.timer = this.cfg.recover;
      game.enemyMelee(this, 54, Math.PI * 0.8, this.dmg);
      game.addEffect('slash', { x: this.x, y: this.y - 26, ang: this.facing, color: 'rgba(255,170,140,.7)', size: 42 });
      game.audio?.play('swing2');
    } else if (this.type === 'wisp') {
      this.state = 'recover';
      this.timer = this.cfg.recover;
      for (let i = -1; i <= 1; i++) {
        game.spawnProjectile({
          x: this.x, y: this.y - 26, ang: this.facing + i * 0.18, speed: 220, dmg: this.dmg,
          color: '#c6a4ff', r: 8, life: 3.4, from: 'enemy',
        });
      }
      game.audio?.play('skill');
    } else if (this.type === 'warden') {
      this.state = 'recover';
      this.timer = this.cfg.recover;
      game.addHazard({ x: p.x, y: p.y, r: 82, delay: 0.65, dur: 0.18, dmg: this.dmg, type: 'slam' });
      game.audio?.play('hit');
    }
  }

  move(dx, dy, game) {
    game.moveEntity(this, dx, dy);
  }

  updateAction(dt, game) {
    const p = game.player;
    switch (this.state) {
      case 'cast': {
        if (this.timer <= 0) {
          this.state = 'recover';
          this.timer = 0.8;
          game.spawnProjectile({ x: this.x, y: this.y - 34, ang: this.facing, speed: 300, dmg: this.dmg, color: '#ffe0a0', r: 7, life: 3, from: 'enemy', kind: 'bone' });
        }
        break;
      }
      case 'slamWindup': {
        this.telegraph = 1;
        if (this.timer <= 0) {
          this.state = 'slam';
          this.timer = 0.25;
          game.addHazard({ x: this.x + Math.cos(this.facing) * 60, y: this.y + Math.sin(this.facing) * 60, r: 70, delay: 0.15, dur: 0.16, dmg: this.dmg, type: 'slam' });
          game.shake(7);
          game.audio?.play('hit');
        }
        break;
      }
      case 'slam': {
        if (this.timer <= 0) { this.state = 'recover'; this.timer = 0.9; }
        break;
      }
      case 'charge':
      case 'hop': {
        const sp = this.dashSpeed;
        this.move(this.chargeDir ? this.chargeDir.x * sp * dt : Math.cos(this.facing) * sp * dt, this.chargeDir ? this.chargeDir.y * sp * dt : Math.sin(this.facing) * sp * dt, game);
        this.walk += dt * 12;
        if (!this.hitPlayer && dist(this, p) < this.r + p.r + 12) {
          this.hitPlayer = true;
          game.hurtPlayer(this.dmg, this);
        }
        if (this.timer <= 0) { this.state = 'recover'; this.timer = this.cfg.recover; }
        break;
      }
      default: break;
    }
  }

  // ---------- BOSS ----------
  updateBoss(dt, game) {
    const p = game.player;
    if (!this.awake) return;
    this.bossTimer -= dt;
    this.walk += dt;
    const hpFrac = this.hp / this.maxHp;
    const newPhase = hpFrac < 0.55 ? 2 : 1;
    if (newPhase !== this.phase) {
      this.phase = newPhase;
      this.state = 'enrage';
      this.timer = 1.4;
      game.onBossPhase?.(newPhase);
    }
    if (this.state === 'enrage') {
      this.timer -= dt;
      if (this.timer <= 0) this.state = 'chase';
      return;
    }
    if (this.bossAttack) {
      this.updateBossAttack(dt, game);
      return;
    }
    // reposition
    const d = dist(this, p);
    if (d > 240) {
      this.move((p.x - this.x) / d * 46 * dt, (p.y - this.y) / d * 46 * dt, game);
    } else if (d < 150) {
      this.move(-(p.x - this.x) / d * 34 * dt, -(p.y - this.y) / d * 34 * dt, game);
    }
    this.facing = lerp(this.facing, Math.atan2(p.y - this.y, p.x - this.x), 1 - Math.exp(-3 * dt));
    if (this.bossTimer <= 0) {
      this.startBossAttack(game);
    }
  }

  startBossAttack(game) {
    const p = game.player;
    const patterns = this.phase === 1
      ? ['slam', 'roots', 'slam', 'summon', 'sweep']
      : ['slam', 'roots', 'nova', 'sweep', 'summon', 'slam'];
    const type = patterns[this.pattern % patterns.length];
    this.pattern++;
    this.bossAttack = { type, t: 0, stage: 0, points: [] };
    this.bossTimer = this.phase === 1 ? 3.2 : 2.45;
    this.state = 'attack';
    game.audio?.play('roar');
    game.shake(5);
    if (type === 'slam') {
      const px = clamp(p.x, 3560, 4280), py = clamp(p.y, 1440, 2120);
      this.bossAttack.points = [{ x: px, y: py, r: 100, delay: 1.05, dur: 0.22, dmg: this.dmg }];
      if (this.phase === 2) {
        for (let i = 0; i < 3; i++) {
          const a = rand(0, TAU), rr = rand(120, 220);
          this.bossAttack.points.push({ x: clamp(px + Math.cos(a) * rr, 3580, 4260), y: clamp(py + Math.sin(a) * rr, 1460, 2100), r: 74, delay: 1.55 + i * 0.16, dur: 0.2, dmg: this.dmg * 0.8 });
        }
      }
    } else if (type === 'roots') {
      const a = Math.atan2(p.y - this.y, p.x - this.x);
      for (let i = 0; i < 7; i++) {
        const xx = this.x + Math.cos(a) * (110 + i * 52);
        const yy = this.y + Math.sin(a) * (90 + i * 45);
        this.bossAttack.points.push({ x: xx, y: yy, r: 54, delay: 0.55 + i * 0.12, dur: 0.18, dmg: this.dmg * 0.9 });
      }
      this.bossAttack.points.push({ x: p.x, y: p.y, r: 72, delay: 1.5, dur: 0.2, dmg: this.dmg });
    } else if (type === 'sweep') {
      const a0 = Math.atan2(p.y - this.y, p.x - this.x);
      for (let i = 0; i < 10; i++) {
        const a = a0 + (i / 10) * TAU;
        this.bossAttack.points.push({ x: this.x + Math.cos(a) * 200, y: this.y + Math.sin(a) * 170, r: 60, delay: 0.7 + i * 0.045, dur: 0.24, dmg: this.dmg * 0.8 });
      }
    } else if (type === 'nova') {
      this.bossAttack.rings = true;
      this.bossAttack.ringT = [0, 0.55, 1.1, 1.65].map((t, i) => ({ t, done: false, r: 120 + i * 90 }));
    } else if (type === 'summon') {
      this.bossAttack.summoned = false;
    }
  }

  updateBossAttack(dt, game) {
    const A = this.bossAttack;
    A.t += dt;
    const p = game.player;
    if (A.type === 'slam') {
      for (const pt of A.points) {
        if (!pt.spawned && A.t >= pt.delay) {
          pt.spawned = true;
          game.addHazard({ x: pt.x, y: pt.y, r: pt.r, delay: 0, dur: pt.dur, dmg: pt.dmg, type: 'bossSlam' });
          game.shake(10);
          game.audio?.play('hit');
          game.addEffect('shock', { x: pt.x, y: pt.y, r: 20, maxR: pt.r * 1.4, color: 'rgba(255,150,80,.6)' });
        }
      }
      if (A.t > 1.2) this.endBossAttack();
    } else if (A.type === 'roots') {
      let all = true;
      for (const pt of A.points) {
        if (!pt.spawned && A.t >= pt.delay) {
          pt.spawned = true;
          game.addHazard({ x: pt.x, y: pt.y, r: pt.r, delay: 0, dur: pt.dur + 0.1, dmg: pt.dmg, type: 'root' });
          game.addEffect('spikes', { x: pt.x, y: pt.y, size: pt.r * 0.8 });
          game.audio?.play('swing');
        }
      }
      if (A.t > 2.1) this.endBossAttack();
    } else if (A.type === 'sweep') {
      for (const pt of A.points) {
        if (!pt.spawned && A.t >= pt.delay) {
          pt.spawned = true;
          game.addHazard({ x: pt.x, y: pt.y, r: pt.r, delay: 0.12, dur: 0.18, dmg: pt.dmg, type: 'root' });
          game.addEffect('spikes', { x: pt.x, y: pt.y, size: pt.r * 0.7 });
        }
      }
      if (A.t > 2.2) this.endBossAttack();
    } else if (A.type === 'nova') {
      for (const ring of A.rings2 || []) { /* unused */ }
      for (const ring of A.rings) {
        if (!ring.done && A.t >= ring.t) {
          ring.done = true;
          game.addEffect('shock', { x: this.x, y: this.y, r: 30, maxR: ring.r + 120, color: 'rgba(255,120,90,.65)', ring: true });
          // ring damage check
          const dd = dist(this, p);
          if (Math.abs(dd - (ring.r + 100)) < 46) game.hurtPlayer(this.dmg * 0.7, this);
          game.audio?.play('ult');
          game.shake(8);
        }
      }
      if (A.t > 2.3) this.endBossAttack();
    } else if (A.type === 'summon') {
      if (!A.summoned && A.t > 0.8) {
        A.summoned = true;
        for (let i = 0; i < 2; i++) {
          const a = rand(0, TAU), rr = rand(160, 250);
          game.spawnMinion('wisp', this.x + Math.cos(a) * rr, this.y + Math.sin(a) * rr);
        }
        game.addEffect('shock', { x: this.x, y: this.y, r: 20, maxR: 180, color: 'rgba(200,150,255,.5)' });
      }
      if (A.t > 1.6) this.endBossAttack();
    }
  }

  endBossAttack() {
    this.bossAttack = null;
    this.state = 'chase';
  }
}

