435:     const step = atk.combo === 3 ? 12 : 7;
436:     this.moveEntity(p, Math.cos(p.facing) * step, Math.sin(p.facing) * step);
437:     this.effects.slash(p.x, p.y - 30, p.facing, atk.combo === 3 ? 'rgba(255,235,180,.85)' : 'rgba(220,255,240,.75)', atk.combo === 3 ? 62 : 50, atk.combo === 3 ? 2.6 : 1.9);
