441:   meleeDamage(combo, dur) {
442:     const p = this.player;
443:     const range = combo === 3 ? 112 : 96;
444:     const arc = combo === 3 ? TAU * 0.86 : TAU * 0.42;
445:     let hits = 0;
446:     for (const e of this.enemies) {
447:       if (e.dead || e.spawnT > 0) continue;
448:       const d = dist(p, e);
449:       if (d > range + e.r) continue;
450:       const a = angleTo(p, e);
451:       const diff = Math.abs(shortAngle(p.facing, a));
452:       if (diff > arc / 2) continue;
453:       const crit = Math.random() < p.crit;
454:       let dmg = (13 + p.level * 1.5) * p.atkPower * (1 + (combo - 1) * 0.13) * rand(0.92, 1.08);
455:       if (crit) dmg *= 1.85;
456:       dmg = Math.round(dmg);
457:       e.hurt(dmg, this, crit, p.x, p.y);
458:       this.stats.dmgDealt = (this.stats.dmgDealt || 0) + dmg;
459:       this.combo++; this.comboTimer = 2.8;
460:       this.effects.hitBurst(e.x, e.y - 34 * (e.scale || 1), crit ? '#ffcf6e' : '#ffe3a0', crit);
461:       this.effects.text(e.x + rand(-8, 8), e.y - 46 * (e.scale || 1), (crit ? '✦ ' : '') + dmg, crit ? '#ffd166' : '#fff3d0', crit ? 23 : 16);
462:       this.hitStop = Math.max(this.hitStop, crit ? 0.055 : 0.032);
463:       this.shake(crit ? 5 : 3);
464:       this.audio.play(crit ? 'crit' : 'hit');
465:       hits++;
466:       if (e.type === 'boss') {
467:         this.ui.bossBar?.(this, true);
468:       }
469:     }
470:     if (hits > 0) p.comboHits = (p.comboHits || 0) + hits;
471:   }
