476:     if (p.sta < 24) { this.audio.play('deny'); return; }
477:     p.sta -= 24;
478:     const mv = { x: 0, y: 0 };
479:     if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) mv.x -= 1;
480:     if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) mv.x += 1;
481:     if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) mv.y -= 1;
482:     if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) mv.y += 1;
483:     mv.x += this.touchMove.x; mv.y += this.touchMove.y;
484:     const l = Math.hypot(mv.x, mv.y);
485:     if (l > 0.2) p.facing = Math.atan2(mv.y, mv.x);
486:     p.dashDir = { x: Math.cos(p.facing), y: Math.sin(p.facing) };
487:     p.dash = 0.18;
488:     p.dashCd = 0.55;
