505:         this.effects.slash(p.x, p.y - 30, p.facing + i * TAU / 4, 'rgba(200,255,230,.8)', 74, 2.2);
506:       }
507:       for (const e of this.enemies) {
508:         if (e.dead) continue;
509:         if (dist(p, e) > 150 + e.r) continue;
510:         let dmg = Math.round((21 + p.level * 2.1) * p.atkPower * rand(0.95, 1.1));
511:         const crit = Math.random() < p.crit;
512:         if (crit) dmg = Math.round(dmg * 1.85);
