  await page.keyboard.down('Space'); await page.waitForTimeout(150); await page.keyboard.up('Space');
  await page.keyboard.press('KeyK'); await page.keyboard.press('KeyQ'); await page.waitForTimeout(250);
  await page.keyboard.press('Escape');
  await page.locator('#pause').waitFor({ state: 'visible' });
  await page.locator('#resumeBtn').click();
  await page.keyboard.down('KeyA'); await page.waitForTimeout(700); await page.keyboard.up('KeyA');
  await page.keyboard.press('KeyF');
  const interactVisible = await page.locator('#interactPrompt').isVisible();
  await page.keyboard.press('Escape');
  await page.locator('#pause').waitFor({ state: 'visible' });
  await page.locator('#quitBtn').click();
  await page.locator('#continueBtn').waitFor({ state: 'visible' });
  const savedClass = await page.evaluate(() => JSON.parse(localStorage.getItem('frontiera_save_v1'))?.cls);
  if (savedClass !== 'ronin') throw new Error(`Save missing/wrong class: ${savedClass}`);
  await page.reload({ waitUntil: 'networkidle' });
  await page.locator('#continueBtn').click();
  await page.waitForFunction(() => !document.querySelector('#hud').classList.contains('hidden'));
  if (await page.locator('#playerName').textContent() !== 'RONIN') throw new Error('Continue did not restore class');
  console.log(JSON.stringify({ desktop: 'ok', interactionPrompt: interactVisible, saveContinue: 'ok', errors }));

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
