  await mobile.goto('http://127.0.0.1:3000/', { waitUntil: 'networkidle' });
  await mobile.evaluate(() => localStorage.clear());
  await mobile.reload({ waitUntil: 'networkidle' });
  await mobile.locator('#startBtn').tap();
  await mobile.waitForFunction(() => !document.querySelector('#hud').classList.contains('hidden'));
  const touchLayer = await mobile.locator('#touchLayer').evaluate(el => getComputedStyle(el).display);
